mapper.select:
SELECT user_id, secret_encrypted, last_used_step, enrolled_at
  FROM identity.totp_credential
 WHERE user_id = #{userId}

mapper.update:
UPDATE identity.totp_credential
   SET last_used_step = #{step}
 WHERE user_id = #{userId}
   AND last_used_step < #{step}

UPDATE identity.recovery_code
   SET used_at = #{usedAt}
 WHERE id = #{id}
   AND used_at IS NULL

mapper.select:
SELECT user_id, consecutive_failures, locked_until
  FROM identity.login_failure
 WHERE user_id = #{userId}

mapper.insert:
INSERT INTO identity.login_failure (user_id, consecutive_failures, locked_until, updated_at)
SELECT u.id, 0, CAST(NULL AS TIMESTAMP WITH TIME ZONE), #{now}
  FROM identity.app_user u
 WHERE u.id = #{userId}
   AND NOT EXISTS (SELECT 1 FROM identity.login_failure f WHERE f.user_id = #{userId})

mapper.update:
UPDATE identity.login_failure
   SET consecutive_failures = 0,
       locked_until = CAST(NULL AS TIMESTAMP WITH TIME ZONE),
       updated_at = #{now}
 WHERE user_id = #{userId}
